     1	package br.com.marealta.dominio;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	public class ReservaService {
     7	
     8	    private final Pousada pousada;
     9	    private final List<OuvinteReserva> ouvintes;
    10	    private final List<Reserva> reservas = new ArrayList<>();
    11	
    12	    public ReservaService(Pousada pousada, List<OuvinteReserva> ouvintes) {
    13	        this.pousada = pousada;
    14	        this.ouvintes = List.copyOf(ouvintes);
    15	    }
    16	
    17	    public synchronized Reserva criar(NovaReserva pedido) {
    18	        if (!pedido.saida().isAfter(pedido.entrada())) {
    19	            throw new ErroNegocio(CodigoErro.INVALID_REQUEST, "A saída deve ser depois da entrada");
    20	        }
    21	        if (pedido.hospedes() < 1) {
    22	            throw new ErroNegocio(CodigoErro.INVALID_REQUEST, "A reserva precisa de ao menos um hóspede");
    23	        }
    24	        Quarto quarto = pousada.quarto(pedido.quarto()).orElseThrow(() ->
    25	                new ErroNegocio(CodigoErro.ROOM_NOT_FOUND, "Quarto " + pedido.quarto() + " não existe"));
    26	        if (pedido.hospedes() > quarto.capacidade()) {
    27	            throw new ErroNegocio(CodigoErro.CAPACITY_EXCEEDED,
    28	                    "O quarto " + quarto.numero() + " comporta até " + quarto.capacidade() + " hóspedes");
    29	        }
    30	        boolean ocupado = reservas.stream().anyMatch(r ->
    31	                r.quarto().equals(quarto) && r.sobrepoe(pedido.entrada(), pedido.saida()));
    32	        if (ocupado) {
    33	            throw new ErroNegocio(CodigoErro.ROOM_UNAVAILABLE,
    34	                    "O quarto " + quarto.numero() + " já está reservado em alguma dessas noites");
    35	        }
    36	        Reserva reserva = new Reserva(reservas.size() + 1, quarto, pedido.nomeHospede(), pedido.emailHospede(),
    37	                pedido.cpfHospede(), pedido.entrada(), pedido.saida(), pedido.hospedes(), pedido.plano());
    38	        reservas.add(reserva);
    39	        return reserva;
    40	    }
    41	
    42	    public synchronized Reserva buscar(int id) {
    43	        if (id < 1 || id > reservas.size()) {
    44	            throw new ErroNegocio(CodigoErro.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
    45	        }
    46	        return reservas.get(id - 1);
    47	    }
    48	
    49	    public synchronized Reserva confirmar(int id) {
    50	        Reserva reserva = buscar(id);
    51	        reserva.confirmar();
    52	        ouvintes.forEach(o -> o.reservaConfirmada(reserva));
    53	        return reserva;
    54	    }
    55	
    56	    public synchronized Reserva cancelar(int id) {
    57	        Reserva reserva = buscar(id);
    58	        boolean estavaConfirmada = reserva.status() == StatusReserva.CONFIRMED;
    59	        reserva.cancelar();
    60	        if (estavaConfirmada) {
    61	            ouvintes.forEach(o -> o.reservaConfirmadaCancelada(reserva));
    62	        }
    63	        return reserva;
    64	    }
    65	
    66	    public synchronized Reserva fazerCheckIn(int id) {
    67	        Reserva reserva = buscar(id);
    68	        reserva.fazerCheckIn();
    69	        return reserva;
    70	    }
    71	
    72	    public synchronized Comprovante fazerCheckOut(int id) {
    73	        Reserva reserva = buscar(id);
    74	        reserva.fazerCheckOut();
    75	        return Comprovante.de(reserva);
    76	    }
    77	
    78	    public synchronized Comprovante segundaVia(int id) {
    79	        Reserva reserva = buscar(id);
    80	        if (!reserva.paga()) {
    81	            throw new ErroNegocio(CodigoErro.OPERATION_NOT_ALLOWED, "Só reserva paga tem comprovante");
    82	        }
    83	        return Comprovante.de(reserva);
    84	    }
    85	
    86	    public synchronized List<Reserva> todas() {
    87	        return List.copyOf(reservas);
    88	    }
    89	}
