     7	public record Preco(int noites, BigDecimal subtotal, BigDecimal desconto, BigDecimal total) {
     8	
     9	    private static final BigDecimal ACRESCIMO_ALTA_TEMPORADA = new BigDecimal("1.20");
    10	
    11	    public static Preco calcular(Quarto quarto, LocalDate entrada, LocalDate saida, PlanoTarifa plano) {
    12	        BigDecimal subtotal = Dinheiro.ZERO;
    13	        int noites = 0;
    14	        for (LocalDate noite = entrada; noite.isBefore(saida); noite = noite.plusDays(1)) {
    15	            subtotal = subtotal.add(precoDaNoite(quarto, noite));
    16	            noites++;
    17	        }
    18	        BigDecimal desconto = plano.descontoSobre(subtotal);
    19	        return new Preco(noites, subtotal, desconto, Dinheiro.arredondar(subtotal.subtract(desconto)));
    20	    }
    21	
    22	    private static BigDecimal precoDaNoite(Quarto quarto, LocalDate noite) {
    23	        BigDecimal diaria = quarto.diaria();
    24	        return Dinheiro.arredondar(altaTemporada(noite) ? diaria.multiply(ACRESCIMO_ALTA_TEMPORADA) : diaria);
    25	    }
    26	
    27	    /** De 15 de dezembro ao fim de fevereiro, e julho inteiro. */
    28	    static boolean altaTemporada(LocalDate noite) {
    29	        int mes = noite.getMonthValue();
    30	        return mes == 1 || mes == 2 || mes == 7 || (mes == 12 && noite.getDayOfMonth() >= 15);
    31	    }
    32	}
