    13	/** Lê e valida o corpo do POST /reservations. */
    14	final class PedidoJson {
    15	
    16	    private PedidoJson() {
    17	    }
    18	
    19	    static NovaReserva ler(ObjectMapper mapper, String corpo) {
    20	        JsonNode json;
    21	        try {
    22	            json = mapper.readTree(corpo);
    23	        } catch (Exception e) {
    24	            throw invalido("O corpo não é um JSON válido");
    25	        }
    26	        if (json == null || !json.isObject()) {
    27	            throw invalido("O corpo deve ser um objeto JSON");
    28	        }
    29	        return new NovaReserva(
    30	                inteiro(json, "roomNumber"),
    31	                texto(json, "guestName"),
    32	                texto(json, "guestEmail"),
    33	                texto(json, "guestCpf"),
    34	                data(json, "checkIn"),
    35	                data(json, "checkOut"),
    36	                inteiro(json, "guests"),
    37	                plano(json));
    38	    }
    39	
    40	    private static String texto(JsonNode json, String campo) {
    41	        JsonNode no = json.get(campo);
    42	        if (no == null || !no.isTextual() || no.asText().isBlank()) {
    43	            throw invalido("Campo '" + campo + "' ausente ou inválido");
    44	        }
    45	        return no.asText();
    46	    }
    47	
    48	    private static int inteiro(JsonNode json, String campo) {
    49	        JsonNode no = json.get(campo);
    50	        if (no == null || !no.isIntegralNumber() || !no.canConvertToInt()) {
    51	            throw invalido("Campo '" + campo + "' ausente ou inválido");
    52	        }
    53	        return no.asInt();
    54	    }
    55	
    56	    private static LocalDate data(JsonNode json, String campo) {
    57	        try {
    58	            return LocalDate.parse(texto(json, campo));
    59	        } catch (DateTimeParseException e) {
    60	            throw invalido("Campo '" + campo + "' deve estar no formato AAAA-MM-DD");
    61	        }
    62	    }
    63	
    64	    private static PlanoTarifa plano(JsonNode json) {
    65	        try {
    66	            return PlanoTarifa.valueOf(texto(json, "ratePlan"));
    67	        } catch (IllegalArgumentException e) {
    68	            throw invalido("Campo 'ratePlan' deve ser STANDARD ou NON_REFUNDABLE");
    69	        }
    70	    }
