    19	public class Rotas {
    20	
    21	    private static final String CSV = "text/csv; charset=utf-8";
    22	
    23	    private final ObjectMapper mapper = new ObjectMapper().enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
    24	    private final Pousada pousada;
