    36	    public void registrar(Javalin app) {
    37	        app.exception(ErroNegocio.class, (e, ctx) -> erro(ctx, e.codigo(), e.getMessage()));
    38	
    39	        app.get("/rooms", ctx -> json(ctx, 200, pousada.quartos().stream().map(Json.QuartoJson::de).toList()));
    40	        app.post("/reservations", ctx -> json(ctx, 201,
    41	                Json.ReservaJson.de(reservas.criar(PedidoJson.ler(mapper, ctx.body())))));
    42	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Json.ReservaJson.de(reservas.buscar(id(ctx)))));
    43	        app.post("/reservations/{id}/confirmation", ctx ->
    44	                json(ctx, 200, Json.ReservaJson.de(reservas.confirmar(id(ctx)))));
    45	        app.post("/reservations/{id}/cancellation", ctx ->
    46	                json(ctx, 200, Json.ReservaJson.de(reservas.cancelar(id(ctx)))));
    47	        app.post("/reservations/{id}/check-in", ctx ->
    48	                json(ctx, 200, Json.ReservaJson.de(reservas.fazerCheckIn(id(ctx)))));
    49	        app.post("/reservations/{id}/check-out", ctx ->
    50	                json(ctx, 200, Json.ComprovanteJson.de(reservas.fazerCheckOut(id(ctx)))));
    51	        app.get("/reservations/{id}/document", ctx ->
    52	                json(ctx, 200, Json.ComprovanteJson.de(reservas.segundaVia(id(ctx)))));
    53	        app.get("/messages", ctx -> json(ctx, 200, caixa.enviadas().stream().map(Json.MensagemJson::de).toList()));
    54	        app.get("/reports/occupancy", ctx -> csv(ctx, relatorios.ocupacao(data(ctx))));
    55	        app.get("/reports/revenue", ctx -> csv(ctx, relatorios.financeiro(mes(ctx))));
    56	    }
