    58	    private static int id(Context ctx) {
    59	        try {
    60	            return Integer.parseInt(ctx.pathParam("id"));
    61	        } catch (NumberFormatException e) {
    62	            throw new ErroNegocio(CodigoErro.RESERVATION_NOT_FOUND, "Reserva " + ctx.pathParam("id") + " não existe");
    63	        }
    64	    }
    65	
    66	    private static LocalDate data(Context ctx) {
    67	        try {
    68	            return LocalDate.parse(String.valueOf(ctx.queryParam("date")));
    69	        } catch (DateTimeParseException e) {
    70	            throw new ErroNegocio(CodigoErro.INVALID_REQUEST, "Parâmetro 'date' deve estar no formato AAAA-MM-DD");
    71	        }
    72	    }
    73	
