    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	public class Relatorios {
    14	
    15	    private final Pousada pousada;
    16	    private final ReservaService reservas;
    17	
    18	    public Relatorios(Pousada pousada, ReservaService reservas) {
    19	        this.pousada = pousada;
    20	        this.reservas = reservas;
    21	    }
    22	
    23	    public String ocupacao(LocalDate noite) {
    24	        List<Reserva> ocupando = reservas.todas().stream()
    25	                .filter(r -> r.paga() && r.ocupaNoite(noite))
    26	                .sorted(Comparator.comparingInt((Reserva r) -> r.quarto().numero()))
    27	                .toList();
    28	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    29	        for (Reserva r : ocupando) {
    30	            csv.append(r.quarto().numero()).append(',').append(r.quarto().tipo()).append(',').append(r.id())
    31	                    .append(',').append(r.entrada()).append(',').append(r.saida()).append('\n');
    32	        }
    33	        // uma reserva paga por quarto e por noite, então cada linha é um quarto ocupado
    34	        return csv.append("total,").append(ocupando.size()).append('/').append(pousada.quartos().size())
    35	                .append('\n').toString();
    36	    }
    37	
    38	    public String financeiro(YearMonth mes) {
    39	        List<Reserva> doMes = reservas.todas().stream()
    40	                .filter(r -> YearMonth.from(r.entrada()).equals(mes) && r.valorRetido().signum() > 0)
    41	                .sorted(Comparator.comparing(Reserva::entrada).thenComparingInt(Reserva::id))
    42	                .toList();
    43	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    44	        BigDecimal soma = BigDecimal.ZERO.setScale(2);
    45	        for (Reserva r : doMes) {
    46	            csv.append(r.id()).append(',').append(r.quarto().numero()).append(',').append(r.entrada())
    47	                    .append(',').append(r.saida()).append(',').append(r.status()).append(',')
    48	                    .append(r.valorRetido().toPlainString()).append('\n');
    49	            soma = soma.add(r.valorRetido());
    50	        }
    51	        return csv.append("total,").append(soma.toPlainString()).append('\n').toString();
    52	    }
    53	}
